  if (event.secretEnv !== undefined) {
    if (!isString(event.secretEnv) || !SECRET_ENV_RE.test(event.secretEnv))
      fail("event.secretEnv must name an environment variable matching /^[A-Z][A-Z0-9_]{0,63}$/");
    secretEnv = event.secretEnv;
