  const maxPerHour = asBoundedInt(rate.maxPerHour, 1, TRIGGER_RATE_CEILING.maxPerHour, "rate.maxPerHour");
  const maxPerDay = asBoundedInt(rate.maxPerDay, 1, TRIGGER_RATE_CEILING.maxPerDay, "rate.maxPerDay");
