  resultSchemaMain({ script: SCRIPT, generate: generateRunnerFileSchema, schemaFile: runnerFileSchemaFile, ledgerFile: RUNNER_FILE_LEDGER_FILE, ledgerProblem: runnerFileLedgerProblem });
}

