    this.matchers = options.globs.map(globToRegExp);
  }

  get dirs(): number {
    return this.watchers.size;
  }

  private note(message: string): void {
    if (this.errors.length < MAX_ERRORS && !this.errors.includes(message)) this.errors.push(message);
  }

